import math,itertools
sig=lambda x:1/(1+math.exp(-x))
p={}
for h,v,c,r,y in itertools.product((0,1),repeat=5):
 hv=1/6 if h==v else 1/3
 pr=sig(.75*h+.5*c)
 py=sig(-.5+2.5*v+1.75*c)
 p[h,v,c,r,y]=hv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def expect_y(**cond):
 inds={'h':0,'v':1,'c':2,'r':3}
 subset=[(k,x) for k,x in p.items() if all(k[inds[n]]==val for n,val in cond.items())]
 return sum(k[4]*x for k,x in subset)/sum(x for k,x in subset)
print('Under the stated SCM:')
for h in (0,1):print(f'E[Y|H={h}]={expect_y(h=h):.6f}')
for c in (0,1):
 for r in (0,1):print(f'E[Y|C={c},R={r}]={expect_y(c=c,r=r):.6f}')
print('Bayes optimal hard-label accuracy:',sum(max(sig(-.5+2.5*v+1.75*c),1-sig(-.5+2.5*v+1.75*c)) for v,c in itertools.product((0,1),repeat=2))/4)
print('Reported split sum:',2849+520+529)
PY"
